function promptPayPayload(id,amount){let x=(id||'').replace(/\D/g,'');if(!x)return '';let target=x.length===10?'0066'+x.slice(1):x.length===13?x:'';if(!target)return '';let aid=tlv('00','A000000677010111')+(x.length===10?tlv('01',target):tlv('02',target));let s=tlv('00','01')+tlv('01','12')+tlv('29',aid)+tlv('53','764')+tlv('54',Number(amount).toFixed(2))+tlv('58','TH')+tlv('59',(db.shopName||'SOURDOUGH').toUpperCase().replace(/[^A-Z0-9 ]/g,'').slice(0,25)||'SOURDOUGH')+tlv('60','THAILAND')+'6304';return s+crc16(s)}
