  $$('#preProducts .preMenuCard').forEach(card=>card.onclick=e=>{let p=db.products.find(x=>x.id===card.dataset.id),x=preCart.find(x=>x.id===p.id);if(e.target.closest('[data-minus]')){e.stopPropagation();if(x){x.qty--;if(x.qty<=0)preCart=preCart.filter(i=>i!==x)}}else if(x)x.qty++;else preCart.push({id:p.id,name:p.name,variant:'',price:p.price,qty:1});clickSound(520,.045);renderPreProducts()})
