let selectedStock=new Set();
function renderStock(){
  const en=db.language==='en';
  const catName=id=>db.categories.find(c=>c.id===id)?.name||id;
  const lowLimit=3;
  const rows=db.products.map((p,i)=>{
    const low=+p.stock<=lowLimit;
    const soldOut=+p.stock<=0;
    const statusText=soldOut?(en?'Out of stock':'สินค้าหมด'):(low?(en?'Low stock':'สต๊อกต่ำ'):(en?'In stock':'ปกติ'));
    return `<div class="stockTableRow ${low?'isLow':''} ${selectedStock.has(p.id)?'selected':''}" data-stock-id="${p.id}" data-stock-cat="${p.cat}">
      <button class="stockProductCell" type="button" onclick="toggleStockPick('${p.id}')" aria-label="${en?'Select':'เลือก'} ${p.name}">
        <span class="stockIndex">${i+1}</span>
        <span class="stockThumb"><img src="${p.img||'logo.png'}" alt=""></span>
        <span class="stockName"><b>${p.name}</b><small>${selectedStock.has(p.id)?(en?'Selected':'เลือกแล้ว'):(en?'Tap to select':'แตะเพื่อเลือก')}</small></span>
      </button>
      <span class="stockCategory">${catName(p.cat)}</span>
      <strong class="stockPrice">${money(p.price)}</strong>
      <div class="stockQtyControl"><button type="button" onclick="stockChange('${p.id}',-1)">−</button><strong>${p.stock}</strong><button type="button" onclick="stockChange('${p.id}',1)">+</button></div>
      <span class="stockStatus ${low?'low':'ok'}"><svg viewBox="0 0 24 24" aria-hidden="true">${low?'<path d="M12 3 2.7 20h18.6L12 3Zm0 5v6m0 3.2v.1"/>':'<circle cx="12" cy="12" r="8"/><path d="m8.5 12 2.2 2.2 4.8-5"/>'}</svg>${statusText}</span>
    </div>`;
  }).join('');
  $('#stockList').innerHTML=`<section class="stockTableCard"><div class="stockTableHead"><span>${en?'Product':'สินค้า'}</span><span>${en?'Category':'หมวดหมู่'}</span><span>${en?'Selling price (฿)':'ราคาขาย (฿)'}</span><span>${en?'Stock remaining':'สต๊อกคงเหลือ'}</span><span>${en?'Status':'สถานะ'}</span></div>${rows||`<div class="emptyState">${en?'No products':'ไม่มีสินค้า'}</div>`}</section>`;
  $('#selectAllStock').textContent=selectedStock.size===db.products.length&&db.products.length?(en?'Clear selection':'ยกเลิกการเลือกทั้งหมด'):(en?'Select all':'เลือกทั้งหมด');
  const jump=$('#stockCategoryJump');
  if(jump){
    const keep=jump.value||'all';
    jump.innerHTML=`<option value="all">${en?'All categories':'ทุกหมวดหมู่'}</option>`+db.categories.map(c=>`<option value="${c.id}">${c.name}</option>`).join('');
    jump.value=[...jump.options].some(o=>o.value===keep)?keep:'all';
  }
}
