/* direct image crop: drag the picture itself; wheel/pinch to zoom */
(function(){
 const modal=$('#imageCropModal'),canvas=$('#cropCanvas'),ctx=canvas?.getContext('2d');
 if(!modal||!canvas||!ctx)return;
 let img=null,target=null,scale=1,ox=0,oy=0,drag=false,lastX=0,lastY=0,pinch=0,isLogo=false,isStaff=false,cropShape='rounded';
 function metrics(){let base=Math.max(640/img.naturalWidth,640/img.naturalHeight),sc=base*scale,w=img.naturalWidth*sc,h=img.naturalHeight*sc;return {w,h}}
 function clamp(){if(!img)return;let {w,h}=metrics(),mx=Math.max(0,(w-640)/2),my=Math.max(0,(h-640)/2);ox=Math.max(-mx,Math.min(mx,ox));oy=Math.max(-my,Math.min(my,oy))}
 function shapePath(c,shape,size=640){let r=size/2;c.beginPath();if(shape==='circle'){c.arc(r,r,r,0,Math.PI*2)}else if(shape==='oval'){c.ellipse(r,r,r,r*.72,0,0,Math.PI*2)}else if(shape==='heart'){let k=size/640;c.moveTo(320*k,570*k);c.bezierCurveTo(270*k,520*k,70*k,390*k,95*k,205*k);c.bezierCurveTo(115*k,60*k,285*k,70*k,320*k,185*k);c.bezierCurveTo(355*k,70*k,525*k,60*k,545*k,205*k);c.bezierCurveTo(570*k,390*k,370*k,520*k,320*k,570*k)}else if(shape==='arch'){c.moveTo(70,590);c.lineTo(70,320);c.arc(320,320,250,Math.PI,0);c.lineTo(570,590);c.closePath()}else if(shape==='rounded'){let rr=70;c.roundRect(0,0,size,size,rr)}else{c.rect(0,0,size,size)}c.closePath()} function draw(){if(!img)return;clamp();ctx.clearRect(0,0,640,640);ctx.save();if(isLogo){shapePath(ctx,cropShape,640);ctx.clip()}else{ctx.fillStyle='#f5eee4';ctx.fillRect(0,0,640,640)}let {w,h}=metrics();ctx.drawImage(img,(640-w)/2+ox,(640-h)/2+oy,w,h);ctx.restore()}
 function close(){modal.classList.add('hidden');document.documentElement.classList.remove('imageCropOpen');img=null;target=null;drag=false;isLogo=false;isStaff=false}
 function zoomBy(d){scale=Math.max(.42,Math.min(4,scale+d));draw()}
 function loadImage(src,preview,opts={}){let im=new Image();im.onload=()=>{img=im;target=preview;isLogo=!!opts.logo;isStaff=!!opts.staff;scale=1;ox=oy=0;cropShape=opts.shape||'rounded';$('#imageCropModal h2').textContent=opts.title||(db.language==='en'?'Adjust product photo':'ปรับรูปสินค้า');$('.cropHint').textContent=isLogo?(db.language==='en'?'Choose a frame shape · drag to position · zoom in or out before saving':'เลือกรูปทรงกรอบ · ลากเพื่อจัดตำแหน่ง · ซูมเข้าออกก่อนบันทึก'):(db.language==='en'?'Drag to reposition · pinch or scroll to zoom':'ลากรูปในกรอบเพื่อจัดตำแหน่ง · ใช้สองนิ้วหรือสกอลล์เพื่อซูม');const chooser=$('#cropShapeChooser');chooser?.classList.toggle('hidden',!isLogo);if(chooser){$('#cropShapeTitle').textContent=db.language==='en'?'Choose frame shape':'เลือกรูปทรงกรอบ';$('#cropZoomLabel').textContent=db.language==='en'?'Zoom':'ซูมรูป';chooser.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.shape===cropShape);const labels={square:['สี่เหลี่ยม','Square'],rounded:['เหลี่ยมมน','Rounded'],circle:['วงกลม','Circle'],oval:['วงรี','Oval'],heart:['หัวใจ','Heart'],arch:['ซุ้มโค้ง','Arch']};b.querySelector('span').textContent=labels[b.dataset.shape][db.language==='en'?1:0]})}document.documentElement.classList.add('imageCropOpen');modal.classList.remove('hidden');modal.classList.toggle('logoCropMode',isLogo||isStaff);modal.scrollTop=0;requestAnimationFrame(()=>{window.scrollTo({top:0,left:0,behavior:'auto'});modal.querySelector('.cropBox')?.scrollIntoView({block:'start',behavior:'auto'});draw()})};im.src=src}
 function openCrop(file,preview,opts={}){if(!file)return;let r=new FileReader();r.onload=()=>loadImage(r.result,preview,opts);r.readAsDataURL(file)}
 window.openImageCrop=(src,preview,opts={})=>loadImage(src,preview,opts);
 canvas.addEventListener('pointerdown',e=>{if(!img)return;drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture?.(e.pointerId)});
 canvas.addEventListener('pointermove',e=>{if(!drag||!img)return;let rect=canvas.getBoundingClientRect(),k=640/rect.width;ox+=(e.clientX-lastX)*k;oy+=(e.clientY-lastY)*k;lastX=e.clientX;lastY=e.clientY;draw()});
 ['pointerup','pointercancel','pointerleave'].forEach(t=>canvas.addEventListener(t,()=>drag=false));
 canvas.addEventListener('wheel',e=>{e.preventDefault();zoomBy(e.deltaY<0?.12:-.12)},{passive:false});
 canvas.addEventListener('touchmove',e=>{if(e.touches.length===2){e.preventDefault();let a=e.touches[0],b=e.touches[1],d=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);if(pinch)zoomBy((d-pinch)/260);pinch=d}},{passive:false});
 canvas.addEventListener('touchend',()=>pinch=0);
 $('#cropZoomIn').onclick=()=>zoomBy(.15);$('#cropZoomOut').onclick=()=>zoomBy(-.15);$('#cropShapeChooser')?.addEventListener('click',e=>{let b=e.target.closest('button[data-shape]');if(!b)return;cropShape=b.dataset.shape;$('#cropShapeChooser').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));draw()});
 $('#cropClose').onclick=close;$('#cropCancel').onclick=close;
 $('#cropApply').onclick=()=>{if(!img||!target)return;draw();let out=document.createElement('canvas');out.width=900;out.height=900;let oc=out.getContext('2d');if(!isLogo){oc.fillStyle='#f5eee4';oc.fillRect(0,0,900,900)}if(isLogo){oc.save();shapePath(oc,cropShape,900);oc.clip()}oc.drawImage(canvas,0,0,900,900);if(isLogo)oc.restore();let data=out.toDataURL((isLogo||isStaff)?'image/png':'image/jpeg',.92);if(isLogo){target.dataset.cropped=data;target.innerHTML=`<img src="${data}" alt="Store logo"><span class="logoEditHint">${db.language==='en'?'Tap to adjust':'แตะเพื่อปรับรูป'}</span>`;target.onclick=()=>window.openImageCrop(data,target,{logo:true,title:db.language==='en'?'Adjust store logo':'ปรับโลโก้ร้าน'});}else if(isStaff){$('#staffEditAvatar').src=data;$('#staffEditAvatarData').value=data;}else{target.dataset.cropped=data;target.innerHTML=`<img src="${data}" alt="รูปที่ครอปแล้ว">`;}close()};
 $('#editImage').addEventListener('change',e=>openCrop(e.target.files[0],$('#imagePreview')));
 $('#editHalfImage').addEventListener('change',e=>openCrop(e.target.files[0],$('#halfImagePreview')));
})();

/* Store logo: remove a flat/light background automatically before crop. */
function removeLogoBackground(file){return new Promise(resolve=>{let r=new FileReader();r.onload=()=>{let im=new Image();im.onload=()=>{let max=1400,k=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*k));c.height=Math.max(1,Math.round(im.naturalHeight*k));let x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0,c.width,c.height);let d=x.getImageData(0,0,c.width,c.height),a=d.data,w=c.width,h=c.height,pts=[[2,2],[w-3,2],[2,h-3],[w-3,h-3]];let bg=[0,0,0];pts.forEach(([px,py])=>{let i=(py*w+px)*4;bg[0]+=a[i];bg[1]+=a[i+1];bg[2]+=a[i+2]});bg=bg.map(v=>v/pts.length);for(let i=0;i<a.length;i+=4){let dr=a[i]-bg[0],dg=a[i+1]-bg[1],dbb=a[i+2]-bg[2],dist=Math.sqrt(dr*dr+dg*dg+dbb*dbb);if(dist<38)a[i+3]=0;else if(dist<82)a[i+3]=Math.round(a[i+3]*(dist-38)/44)}x.putImageData(d,0,0);resolve(c.toDataURL('image/png'))};im.src=r.result};r.readAsDataURL(file)})}

// V4.2: auto-close payment success screen after 5 seconds with animated countdown
let successTimer=null;
function closeSuccessAndReset(){
  if(successTimer){clearInterval(successTimer);successTimer=null}
  $('#successModal').classList.add('hidden');
  $('#salePulse').textContent='พร้อมรับออเดอร์ใหม่';
}
function startSuccessCountdown(){
  if(successTimer) clearInterval(successTimer);
  let remaining=5;
  const sec=$('#successSeconds'), ringSec=$('#ringSeconds'), ring=$('#countRingProgress');
  const circumference=2*Math.PI*18;
  const paint=()=>{if(sec)sec.textContent=remaining;if(ringSec)ringSec.textContent=remaining;if(ring)ring.style.strokeDashoffset=String(circumference*(1-remaining/5))};
  paint();
  successTimer=setInterval(()=>{remaining-=1;paint();if(remaining<=0){clearInterval(successTimer);successTimer=null;setTimeout(closeSuccessAndReset,180)}},1000);
}


// V4.4 held orders drawer from bottom navigation
(function(){
  const drawer=$('#heldDrawer'), backdrop=$('#heldDrawerBackdrop'), btn=$('#heldNavBtn'), close=$('#heldDrawerClose');
  function setHeldDrawer(open){if(!drawer)return;drawer.classList.toggle('open',open);if(backdrop)backdrop.classList.toggle('hidden',!open);} window.setHeldDrawerState=setHeldDrawer;
  if(btn)btn.onclick=()=>{renderHeld();setHeldDrawer(!drawer.classList.contains('open'))};
  if(close)close.onclick=()=>setHeldDrawer(false);
  if(backdrop)backdrop.onclick=()=>setHeldDrawer(false);
})();

/* ===== V5.1: prevent pinch/double-tap zoom on touch devices ===== */
['gesturestart','gesturechange','gestureend'].forEach(function(type){
  document.addEventListener(type,function(e){ e.preventDefault(); },{passive:false});
});
let lastTouchEnd=0;
document.addEventListener('touchend',function(e){
  const now=Date.now();
  if(now-lastTouchEnd<=300){ e.preventDefault(); }
  lastTouchEnd=now;
},{passive:false});


