function checkCartLowStock(p){if(!p||p.lowStockAlerted)return;const inCart=cart.filter(i=>i.id===p.id).reduce((n,i)=>n+(+i.qty||0),0),remaining=Math.max(0,(+p.stock||0)-inCart);if(remaining<=LOW_STOCK_LIMIT){p.lowStockAlerted=true;p.lowStockAlertedAt=Date.now();save();showLowStockToast([p]);speakLocalized('สต๊อกต่ำ กรุณาเติมสต๊อก','Low stock. Please restock.',{priority:true});if(remaining<=0)setTimeout(()=>go('stock'),220)}}
function checkLowStockAlerts(){
  const newlyLow=[];
  (db.products||[]).forEach(p=>{
    syncLowStockReset(p);
    if(+p.stock<=LOW_STOCK_LIMIT && !p.lowStockAlerted){p.lowStockAlerted=true;p.lowStockAlertedAt=Date.now();newlyLow.push(p);}
  });
  if(!newlyLow.length)return;
  save();
  clickSound(740,.16);
  showLowStockToast(newlyLow);
  speakLocalized('สต๊อกต่ำ กรุณาเติมสต๊อก','Low stock. Please restock.');
  if(newlyLow.some(p=>+p.stock<=0))setTimeout(()=>go('stock'),220);
}
/* ===== v5.50 pre-order due reminder ===== */
(function(){
  const LEAD_MINUTES=30;
  function pickupDate(p){
    if(!p?.date||!p?.time)return null;
    const d=new Date(`${p.date}T${p.time}:00`);
    return Number.isNaN(d.getTime())?null:d;
  }
  function reminderTone(){
    try{
      audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();
      [0,0.18,0.36].forEach((delay,i)=>{
        const o=audioCtx.createOscillator(),g=audioCtx.createGain();
        o.frequency.value=[660,820,980][i];g.gain.value=.055;o.connect(g);g.connect(audioCtx.destination);
        o.start(audioCtx.currentTime+delay);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+delay+.16);o.stop(audioCtx.currentTime+delay+.17);
      });
    }catch(e){}
  }
  function speakReminder(p){
    speakLocalized(`แจ้งเตือนรายการสั่งล่วงหน้า ลูกค้า ${p.customer||''} เวลารับ ${p.time} นาฬิกา`,`Pre-order reminder. Customer ${p.customer||''}. Pickup at ${p.time}.`);
  }
  function showReminder(p,mins){
    document.querySelector('.preReminderToast')?.remove();
    const en=db.language==='en', el=document.createElement('div');el.className='preReminderToast';
    el.innerHTML=`<svg viewBox="0 0 24 24"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9Z"/><path d="M10 20h4"/></svg><div><small>${en?'PRE-ORDER REMINDER':'แจ้งเตือนสั่งล่วงหน้า'}</small><b>${en?'Customer':'ลูกค้า'}: ${p.customer||'-'}</b><span>${en?'Pickup':'เวลารับ'} ${p.time} · ${en?`in about ${Math.max(0,mins)} min`:`อีกประมาณ ${Math.max(0,mins)} นาที`}</span></div><button type="button" aria-label="Close">×</button>`;
    el.querySelector('button').onclick=()=>el.remove();document.body.appendChild(el);setTimeout(()=>el.remove(),15000);
  }
  function checkPreorderReminders(){
    const now=new Date(); let changed=false;
    (db.preorders||[]).forEach(p=>{
      if(p.remindedAt)return; const due=pickupDate(p); if(!due)return;
      const diff=(due-now)/60000;
      if(diff<=LEAD_MINUTES && diff>=-5){p.remindedAt=Date.now();changed=true;reminderTone();speakReminder(p);showReminder(p,Math.ceil(diff));}
    });
    if(changed)save();
  }
  // Browser audio requires a user interaction first; unlock audio on the first tap/click.
  document.addEventListener('pointerdown',()=>{try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume?.()}catch(e){}},{once:true});
  setTimeout(checkPreorderReminders,1200);setInterval(checkPreorderReminders,30000);
  window.checkPreorderReminders=checkPreorderReminders;
})();
